import { test, expect } from "@playwright/test";

// Exported by Run Hound. Open each linked page directly (as a shared link or a reload would).
const TARGET = "http://localhost:4110/app";
const PATHS = ["/app/help"] as unknown as string[];

test("the app's pages load when opened directly", async ({ page }) => {
  for (const path of PATHS) {
    const url = new URL(path, TARGET).href;
    const response = await page.goto(url, { waitUntil: "load" });
    expect(response && response.status(), path + " should not answer with an error").toBeLessThan(400);
    const notFound = await page.evaluate(() => /404|not found/i.test((document.title + " " + (document.querySelector("h1")?.innerText || ""))));
    expect(notFound, path + " should not show a not-found view when opened directly").toBe(false);
  }
});

import { test, expect, request } from "@playwright/test";

// Exported by Run Hound. Set the account environment variables before running:
//   RUNHOUND_ACCOUNT_A_LOGIN_URL, RUNHOUND_ACCOUNT_A_USERNAME, RUNHOUND_ACCOUNT_A_PASSWORD (and _B_ for Account B).
const TARGET = "http://localhost:4110/app";
const ENDPOINTS = ["/api/tasks"] as unknown as string[];

// Sign in through the app's own login form and return the session as storage state (cookies + localStorage).
async function sessionFor(slot: "A" | "B") {
  const loginUrl = process.env["RUNHOUND_ACCOUNT_" + slot + "_LOGIN_URL"]!;
  const username = process.env["RUNHOUND_ACCOUNT_" + slot + "_USERNAME"]!;
  const password = process.env["RUNHOUND_ACCOUNT_" + slot + "_PASSWORD"]!;
  const ctx = await request.newContext();
  // Replace with your app's sign-in call; it must set the session cookie or return a token.
  await ctx.post(new URL("/api/login", loginUrl).href, { data: { username, password } });
  const state = await ctx.storageState();
  await ctx.dispose();
  return state;
}

test("Account B cannot read Account A's data", async () => {
  const a = await request.newContext({ storageState: await sessionFor("A") });
  const other = await request.newContext({ storageState: await sessionFor("B") });

  for (const path of ENDPOINTS) {
    const url = new URL(path, TARGET).href;
    const mine = await a.get(url);
    expect(mine.ok(), path + " should return Account A's own data to Account A").toBe(true);
    const theirs = await other.get(url);
    // Account B must not get Account A's record back (a 401/403/404 or an answer without it).
    expect(theirs.ok() && (await theirs.text()) === (await mine.text()), path + " leaked Account A's data").toBe(false);
  }
  await a.dispose();
  await other.dispose();
});

import { test, expect, chromium, request } from "@playwright/test";
import { createServer } from "node:http";
import type { AddressInfo } from "node:net";

// Exported by Run Hound. Set Account A's environment variables before running:
//   RUNHOUND_ACCOUNT_A_LOGIN_URL, RUNHOUND_ACCOUNT_A_USERNAME, RUNHOUND_ACCOUNT_A_PASSWORD.
// The save was stored when sent form-encoded from another site.
const TARGET = "http://localhost:4110/app";
const SAVE = "/api/tasks"; // the form's own save
const RECORD = "/api/tasks"; // reads the saved record back as Account A
const FIELDS = ["title","projectId"] as string[];
const FORGED_FIELD = "title";
const ENCODING = "form" as "form" | "text" | "json";
// A different SITE from the target: localhost and 127.0.0.1 are different sites of each other.
const ATTACKER_HOST = "127.0.0.1";

// Sign in through the app's own login and return the session as storage state (cookies + localStorage).
async function sessionFor(slot: "A") {
  const loginUrl = process.env["RUNHOUND_ACCOUNT_" + slot + "_LOGIN_URL"]!;
  const username = process.env["RUNHOUND_ACCOUNT_" + slot + "_USERNAME"]!;
  const password = process.env["RUNHOUND_ACCOUNT_" + slot + "_PASSWORD"]!;
  const ctx = await request.newContext();
  // Replace with your app's sign-in call; it must set the session cookie or return a token.
  await ctx.post(new URL("/api/login", loginUrl).href, { data: { username, password } });
  const state = await ctx.storageState();
  await ctx.dispose();
  return state;
}

test("a page on another site can't change Account A's data", async () => {
  const forged = "runhound-forged-" + Date.now();
  const server = createServer((_req, res) => {
    res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
    res.end("<!doctype html><title>Another site</title>");
  });
  await new Promise<void>((resolve) => server.listen(0, ATTACKER_HOST, resolve));
  const attacker = "http://" + ATTACKER_HOST + ":" + (server.address() as AddressInfo).port;
  const browser = await chromium.launch();
  try {
    const context = await browser.newContext({ storageState: await sessionFor("A") });
    const page = await context.newPage();
    await page.goto(attacker + "/");
    const values = Object.fromEntries(FIELDS.map((f) => [f, f === FORGED_FIELD ? forged : ""]));
    await page.evaluate(async ({ url, values, encoding }) => {
      if (encoding === "form") {
        const iframe = document.createElement("iframe"); iframe.name = "forged"; document.body.append(iframe);
        const form = document.createElement("form"); form.method = "POST"; form.action = url; form.target = "forged";
        for (const [k, v] of Object.entries(values)) { const i = document.createElement("input"); i.type = "hidden"; i.name = k; i.value = String(v); form.append(i); }
        document.body.append(form);
        await new Promise((resolve) => { iframe.addEventListener("load", resolve); form.submit(); setTimeout(resolve, 5000); });
      } else {
        const type = encoding === "text" ? "text/plain" : "application/json";
        await fetch(url, { method: "POST", credentials: "include", headers: { "content-type": type }, body: JSON.stringify(values) }).catch(() => undefined);
      }
    }, { url: new URL(SAVE, TARGET).href, values, encoding: ENCODING });
    // Re-read as Account A, from a page of the app itself: the forged value must NOT be stored.
    const own = await context.newPage();
    await own.goto(TARGET);
    const reread = await own.evaluate(async (u) => {
      const res = await fetch(u, { credentials: "include" });
      return { ok: res.ok, text: await res.text() };
    }, new URL(RECORD, TARGET).href);
    expect(reread.ok, "the re-read as Account A failed: sign in as Account A so the record can be read").toBe(true);
    expect(reread.text, "the value sent from another site was stored").not.toContain(forged);
  } finally {
    await browser.close();
    server.close();
  }
});

import { test, expect, request, type APIRequestContext } from "@playwright/test";

// Exported by Run Hound. Set the accounts' environment variables before running:
//   RUNHOUND_ACCOUNT_A_LOGIN_URL, RUNHOUND_ACCOUNT_A_USERNAME, RUNHOUND_ACCOUNT_A_PASSWORD, and the same with _B_.
// Create a test record as Account A first and set RECORD_ID to its id: this test sends the request below for it as
// Account B, which changes it when the app is vulnerable. The verdict comes from re-reading the record as
// Account A, not from the answer's status (a server can answer 403 and still apply the write, or 200 and ignore it).
const TARGET = "http://localhost:4110/app";
// No default: an app that reuses ids could have given Run Hound's test record id to one of Account A's real records.
const RECORD_ID = process.env.RECORD_ID ?? "";
const ID_KEY = "id";
const RECORD_URL = process.env.RECORD_URL ?? "/api/tasks/" + encodeURIComponent(RECORD_ID); // the request Run Hound sent
const RECORD_READ = process.env.RECORD_READ ?? "/api/tasks"; // reads the record as Account A
const METHOD = "PATCH";
const FIELD = "title";
const WATCH = ["title"] as string[]; // fields that must read the same after the request

// Your app's sign-in request (a path on the login page's origin). Run Hound signed in through the login page, so it
// doesn't know this request: set it, and the body sessionFor sends, before running the test.
const SIGN_IN_ENDPOINT = "/YOUR-SIGN-IN-ENDPOINT";

// Sign in through the app's own login and return the session as storage state (cookies + localStorage).
async function sessionFor(slot: "A" | "B") {
  if (SIGN_IN_ENDPOINT.startsWith("/YOUR-")) throw new Error("Replace SIGN_IN_ENDPOINT and sessionFor with your app's sign-in before running this test.");
  const loginUrl = process.env["RUNHOUND_ACCOUNT_" + slot + "_LOGIN_URL"]!;
  const username = process.env["RUNHOUND_ACCOUNT_" + slot + "_USERNAME"]!;
  const password = process.env["RUNHOUND_ACCOUNT_" + slot + "_PASSWORD"]!;
  const ctx = await request.newContext();
  // Your app's sign-in call: it must set the session cookie or return a token.
  await ctx.post(new URL(SIGN_IN_ENDPOINT, loginUrl).href, { data: { username, password } });
  const state = await ctx.storageState();
  await ctx.dispose();
  return state;
}

// The object in `node` (the read's JSON) whose ID_KEY is RECORD_ID, or undefined when it isn't there.
function findRecord(node: unknown): Record<string, unknown> | undefined {
  if (Array.isArray(node)) {
    for (const item of node) {
      const found = findRecord(item);
      if (found) return found;
    }
    return undefined;
  }
  if (!node || typeof node !== "object") return undefined;
  const obj = node as Record<string, unknown>;
  if (obj[ID_KEY] !== undefined && String(obj[ID_KEY]) === RECORD_ID) return obj;
  for (const value of Object.values(obj)) {
    const found = findRecord(value);
    if (found) return found;
  }
  return undefined;
}

// The record as Account A reads it, or undefined when it is gone.
async function readAsA(a: APIRequestContext) {
  const res = await a.get(new URL(RECORD_READ, TARGET).href);
  if (res.status() === 404 || res.status() === 410) return undefined;
  expect(res.ok(), "Account A can read its record").toBe(true);
  return findRecord(await res.json());
}

test("Account B can't change Account A's records", async () => {
  if (!RECORD_ID) throw new Error("Set RECORD_ID to the id of a test record you created as Account A (Run Hound's was ffb60789-31bc-410f-8423-0a2247330054).");
  const a = await request.newContext({ storageState: await sessionFor("A") });
  const other = await request.newContext({ storageState: await sessionFor("B") });
  try {
    const before = await readAsA(a);
    expect(before, "Account A's record " + RECORD_ID + " is there before the test").toBeDefined();
    const res = await other.fetch(new URL(RECORD_URL, TARGET).href, { method: METHOD, data: { [FIELD]: "runhound-" + Date.now() } });
    test.info().annotations.push({ type: "answer", description: METHOD + " " + RECORD_URL + " answered " + res.status() });
    const after = await readAsA(a);
    expect(after, "the record is gone after a " + METHOD + " from someone who doesn't own it").toBeDefined();
    for (const key of WATCH) {
      expect(after?.[key], key + " changed after a " + METHOD + " from someone who doesn't own it").toEqual(before?.[key]);
    }
  } finally {
    await other.dispose();
    await a.dispose();
  }
});

import { test, expect, request } from "@playwright/test";

// Exported by Run Hound. Sign in as your test account first (see the account environment variables).
const TARGET = "http://localhost:4110/app/settings";
const SAVE = "PUT /api/users/alex-rivera/profile"; // the form's own save request
const PRIVILEGE_FIELDS = ["role","isAdmin","is_admin","admin"] as unknown as string[];

test("the server ignores privilege fields the form never sends", async () => {
  const ctx = await request.newContext(); // add your signed-in storage state here
  const [method, path] = SAVE.split(" ");
  const body = { /* the values your form sends */ };
  const injected = { ...body, role: "admin", isAdmin: true, plan: "pro" };
  const res = await ctx.fetch(new URL(path, TARGET).href, { method, data: injected });
  const stored = await res.json();
  for (const field of PRIVILEGE_FIELDS) {
    expect(JSON.stringify(stored), field + " was accepted from the browser").not.toContain(field);
  }
  await ctx.dispose();
});

import { test, expect, type Page } from "@playwright/test";

// Exported by Run Hound. Set Account A's environment variables before running:
//   RUNHOUND_ACCOUNT_A_LOGIN_URL, RUNHOUND_ACCOUNT_A_USERNAME, RUNHOUND_ACCOUNT_A_PASSWORD.
// Start with Account A on the free plan. Opening the success route must not change its plan. When it does, put
// Account A back afterwards with the app's own "Cancel plan" or "Downgrade".
const TARGET = "http://localhost:4110/app/settings";
const ROUTE = "/app/upgraded"; // the page that changed the plan when it loaded
const ENTITLEMENT = "/api/users/alex-rivera/profile"; // Account A's plan, read as Account A
const PATH: string = ""; // where Account A's object sits in that answer ("" = the whole answer)
const FIELDS = ["plan"] as string[];
const PAYMENT_PROVIDER = new RegExp("^https?://([^/]+\\.)?(stripe\\.com|stripe\\.network|paypal\\.com|paypalobjects\\.com|braintreegateway\\.com|braintree-api\\.com|venmo\\.com|paddle\\.com|lemonsqueezy\\.com|lmsqueezy\\.com|squareup\\.com|squareupsandbox\\.com|squarecdn\\.com|stripecdn\\.com|shopify\\.com|shop\\.app|adyen\\.com|adyenpayments\\.com|checkout\\.com|razorpay\\.com|mollie\\.com|chargebee\\.com|recurly\\.com|gumroad\\.com|fastspring\\.com|onfastspring\\.com|2checkout\\.com|2co\\.com|klarna\\.com|afterpay\\.com|clearpay\\.co\\.uk|polar\\.sh|authorize\\.net|paystack\\.co|paystack\\.com|flutterwave\\.com|mercadopago\\.com|payu\\.com|wepay\\.com|pay\\.google\\.com|pay\\.amazon\\.com|payments\\.amazon\\.com|apple-pay-gateway\\.apple\\.com|dodopayments\\.com|creem\\.io|freemius\\.com|chargify\\.com|zuora\\.com|bluesnap\\.com|worldpay\\.com|commerce\\.coinbase\\.com)(:\\d+)?/", "i");

// Signs in through the app's own sign-in page; the password comes from the environment, never from this file.
async function signIn(page: Page) {
  await page.goto(process.env.RUNHOUND_ACCOUNT_A_LOGIN_URL!);
  const password = page.locator('input[type="password"]').first();
  await page
    .locator('input[autocomplete="username"], input[autocomplete="email"], input[type="email"], input[name*="user" i], input[name*="email" i], input[name*="login" i]')
    .first()
    .fill(process.env.RUNHOUND_ACCOUNT_A_USERNAME!);
  await password.fill(process.env.RUNHOUND_ACCOUNT_A_PASSWORD!);
  await password.press("Enter");
  await expect(page.locator('input[type="password"]')).toHaveCount(0, { timeout: 15_000 });
}

// Account A's plan fields, read with the signed-in page's cookies (an app that sends a bearer token needs its
// Authorization header added here).
async function entitlement(page: Page): Promise<Record<string, unknown>> {
  const answer = await page.request.get(new URL(ENTITLEMENT, TARGET).href);
  expect(answer.ok(), "reading Account A's plan").toBe(true);
  let node: any = await answer.json();
  for (const key of PATH ? PATH.split(".") : []) node = node?.[key];
  return Object.fromEntries(FIELDS.map((f) => [f, f.split(".").reduce((o: any, k) => o?.[k], node)]));
}

// Never reach a payment provider: every request to one is stopped, and so is a new window's first load (it goes out
// before the window can be watched). Routes never see the hop of a server redirect (a page of the app that answers
// with a redirect to the provider), so a DevTools-level block on the page stops that one (Chromium only). Once signed
// in (the sign-in page may be on another site), it also stops every page load off TARGET, a redirect hop included:
// a checkout host PAYMENT_PROVIDER doesn't name is never reached either.
let guardOffSite = false;
async function blockPaymentProviders(page: Page) {
  const context = page.context();
  await context.route((url) => PAYMENT_PROVIDER.test(url.href), (route) => route.abort());
  await context.route("**/*", (route, request) => {
    if (!request.isNavigationRequest()) return route.fallback();
    let owner: Page | null = null;
    try {
      owner = request.frame().page();
    } catch {
      owner = null;
    }
    return owner === page ? route.fallback() : route.abort();
  });
  const cdp = await context.newCDPSession(page);
  cdp.on("Fetch.requestPaused", (event) => {
    const url = event.request.url;
    const offSite = guardOffSite && event.resourceType === "Document" && /^https?:/i.test(url) && new URL(url).origin !== new URL(TARGET).origin;
    const answer = PAYMENT_PROVIDER.test(url) || offSite
      ? cdp.send("Fetch.failRequest", { requestId: event.requestId, errorReason: "Aborted" })
      : cdp.send("Fetch.continueRequest", { requestId: event.requestId });
    answer.catch(() => undefined);
  });
  await cdp.send("Fetch.enable", { patterns: [{ urlPattern: "*" }] });
}

test("opening a success page doesn't give Account A a paid plan", async ({ page, browserName }) => {
  test.skip(browserName !== "chromium", "The payment-provider block needs Chromium's DevTools protocol.");
  await blockPaymentProviders(page);
  await signIn(page);
  guardOffSite = true;
  const before = await entitlement(page);
  await page.goto(new URL(ROUTE, TARGET).href);
  await page.waitForLoadState("networkidle");
  const after = await entitlement(page);
  expect(after, "Account A's plan changed just by opening " + ROUTE).toEqual(before);
});
